namespace sv_c5c239283af2429fa1b37d3e29b2ce36.Services;

/// <summary>
/// Scoped service that holds the latest low-stock alert count and
/// exposes a change event so any subscribed component can re-render.
/// Polling is owned by the component that starts it; this service is
/// the shared data + notification hub.
/// </summary>
public class InventoryAlertState
{
    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever <see cref="LowStockCount"/> changes.
    /// Subscribers that run on a background thread must wrap
    /// <c>StateHasChanged</c> in <c>InvokeAsync</c>.
    /// </summary>
    public event Action? OnChange;

    public void SetCount(int count)
    {
        LowStockCount = count;
        OnChange?.Invoke();
    }
}
